/* gt.thrownobj (decl.c) tracks an object until it lands */

/**
 * C ref: dothrow.c:39
 * @param {CInt} pm
 * @param {CPtr<struct obj>} ammo
 * @param {CPtr<struct obj>} launcher
 * @returns {CInt}
 */
export function multishot_class_bonus(pm, ammo, launcher) {
    let multishot = 0;
    let skill = cptr.ld1so2(
        objects,
        cptr.ldI16o(ammo, $obj_otyp),
        $sizeof_objclass,
        $objclass_oc_subtyp
    );

    switch (pm) {
        case NHC.PM_CAVE_DWELLER:
        /* give bonus for low-tech gear */
        if (skill == -21 || skill == NHC.P_SPEAR)
            multishot++;
        break;
        case NHC.PM_MONK:
        /* allow higher volley count despite skill limitation */
        if (skill == -24)
            multishot++;
        break;
        case NHC.PM_RANGER:
        /* arbitrary; encourage use of other missiles beside daggers */
        if (skill != NHC.P_DAGGER)
            multishot++;
        break;
        case NHC.PM_ROGUE:
        /* possibly should add knives... */
        if (skill == NHC.P_DAGGER)
            multishot++;
        break;
        case NHC.PM_NINJA:
        if (skill == -24 || skill == -23)
            multishot++;
        // @FallThrough
        ;
        case NHC.PM_SAMURAI:
        /* role-specific launcher and its ammo */
        if (cptr.ldI16o(ammo, $obj_otyp) == NHC.YA &&
                launcher &&
                cptr.ldI16o(launcher, $obj_otyp) == NHC.YUMI)
            multishot++;
        break;
        default:
        break;  /* No bonus */
    }

    return multishot;
}

