            if ((uwep.v &&
                    cptr.ld1so2(
                        objects,
                        cptr.ldI16o(uwep.v, $obj_otyp),
                        $sizeof_objclass,
                        $objclass_oc_subtyp
                    ) ==
                        NHC.P_SLING))
                oammo = otmp;
            else if (ammo_and_launcher(otmp, uswapwep.v))
                altammo = otmp;
            else if (!omisc)
                omisc = otmp;
